-- Main database schema (schema version 2).
-- Timestamps are Unix milliseconds stored as integers.
-- Captured from the legacy runtime on 2026-10-09, with datetime columns changed to integer.
-- Changes after the capture are made here by hand; the runtime adds missing tables, columns, and indexes at startup.
CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`username` text NOT NULL,`email` text NOT NULL,`password_hash` text NOT NULL,`nickname` text,`avatar` text,`phone` text,`role` text DEFAULT "user",`status` text DEFAULT "active",`daily_quota` integer DEFAULT 100,`used_quota` integer DEFAULT 0,`total_creations` integer DEFAULT 0,`last_login_at` integer,`last_login_ip` text,`created_at` integer,`updated_at` integer,`deleted_at` integer);
CREATE INDEX `idx_users_deleted_at` ON `users`(`deleted_at`);
CREATE INDEX `idx_users_status` ON `users`(`status`);
CREATE INDEX `idx_users_role` ON `users`(`role`);
CREATE UNIQUE INDEX `idx_users_email` ON `users`(`email`);
CREATE UNIQUE INDEX `idx_users_username` ON `users`(`username`);
CREATE TABLE `ai_models` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`name` text NOT NULL,`provider` text NOT NULL,`model_name` text NOT NULL,`api_key` text NOT NULL,`base_url` text,`is_default` numeric DEFAULT false,`is_active` numeric DEFAULT true,`is_system_builtin` numeric DEFAULT false,`description` text,`capabilities` JSON,`created_at` integer,`updated_at` integer);
CREATE INDEX `idx_ai_models_provider` ON `ai_models`(`provider`);
CREATE INDEX `idx_ai_models_user_id` ON `ai_models`(`user_id`);
CREATE TABLE `ai_model_usage_logs` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`ai_model_id` integer NOT NULL,`creation_id` integer,`provider` text NOT NULL,`model_name` text NOT NULL,`tool` text,`request_type` text NOT NULL,`input_content` text,`output_content` text,`prompt_tokens` integer,`completion_tokens` integer,`total_tokens` integer,`status` text DEFAULT "success",`error_message` text,`response_time_ms` integer,`extra_data` JSON,`created_at` integer);
CREATE INDEX `idx_ai_model_usage_logs_created_at` ON `ai_model_usage_logs`(`created_at`);
CREATE INDEX `idx_ai_model_usage_logs_status` ON `ai_model_usage_logs`(`status`);
CREATE INDEX `idx_ai_model_usage_logs_request_type` ON `ai_model_usage_logs`(`request_type`);
CREATE INDEX `idx_ai_model_usage_logs_tool` ON `ai_model_usage_logs`(`tool`);
CREATE INDEX `idx_ai_model_usage_logs_provider` ON `ai_model_usage_logs`(`provider`);
CREATE INDEX `idx_ai_model_usage_logs_creation_id` ON `ai_model_usage_logs`(`creation_id`);
CREATE INDEX `idx_ai_model_usage_logs_ai_model_id` ON `ai_model_usage_logs`(`ai_model_id`);
CREATE INDEX `idx_ai_model_usage_logs_user_id` ON `ai_model_usage_logs`(`user_id`);
CREATE TABLE `oauth_platforms` (`id` integer PRIMARY KEY AUTOINCREMENT,`platform_id` text NOT NULL,`platform_name` text NOT NULL,`description` text,`login_url` text,`platform_icon` text,`o_auth_config` JSON,`litellm_config` JSON,`quota_config` JSON,`is_enabled` numeric DEFAULT true,`created_at` integer,`updated_at` integer);
CREATE INDEX `idx_oauth_platforms_is_enabled` ON `oauth_platforms`(`is_enabled`);
CREATE UNIQUE INDEX `idx_oauth_platforms_platform_id` ON `oauth_platforms`(`platform_id`);
CREATE TABLE `oauth_accounts` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`platform` text NOT NULL,`account_name` text NOT NULL,`encrypted_credentials` text NOT NULL,`quota_used` integer DEFAULT 0,`quota_limit` integer DEFAULT 100000,`is_active` numeric DEFAULT true,`is_expired` numeric DEFAULT false,`expires_at` integer,`last_used_at` integer,`extra_data` JSON,`created_at` integer,`updated_at` integer);
CREATE INDEX `idx_oauth_accounts_is_expired` ON `oauth_accounts`(`is_expired`);
CREATE INDEX `idx_oauth_accounts_is_active` ON `oauth_accounts`(`is_active`);
CREATE INDEX `idx_oauth_accounts_platform` ON `oauth_accounts`(`platform`);
CREATE INDEX `idx_oauth_accounts_user_id` ON `oauth_accounts`(`user_id`);
CREATE TABLE `oauth_usage_logs` (`id` integer PRIMARY KEY AUTOINCREMENT,`account_id` integer NOT NULL,`model` text,`prompt_tokens` integer,`completion_tokens` integer,`total_tokens` integer,`request_data` JSON,`response_data` JSON,`error_message` text,`created_at` integer);
CREATE INDEX `idx_oauth_usage_logs_created_at` ON `oauth_usage_logs`(`created_at`);
CREATE INDEX `idx_oauth_usage_logs_model` ON `oauth_usage_logs`(`model`);
CREATE INDEX `idx_oauth_usage_logs_account_id` ON `oauth_usage_logs`(`account_id`);
CREATE TABLE `desktop_bootstrap_devices` (`id` integer PRIMARY KEY AUTOINCREMENT,`device_id` text NOT NULL,`platform` text NOT NULL,`hardware_uuid_hash` text,`serial_hash` text,`board_serial_hash` text,`mac_hashes` JSON,`risk_status` text DEFAULT "trusted",`risk_score` integer DEFAULT 0,`upstream_provider` text,`upstream_token` text,`upstream_registered_at` integer,`last_seen_at` integer,`extra_data` JSON,`created_at` integer,`updated_at` integer);
CREATE INDEX `idx_desktop_bootstrap_devices_risk_status` ON `desktop_bootstrap_devices`(`risk_status`);
CREATE INDEX `idx_desktop_bootstrap_devices_board_serial_hash` ON `desktop_bootstrap_devices`(`board_serial_hash`);
CREATE INDEX `idx_desktop_bootstrap_devices_serial_hash` ON `desktop_bootstrap_devices`(`serial_hash`);
CREATE INDEX `idx_desktop_bootstrap_devices_hardware_uuid_hash` ON `desktop_bootstrap_devices`(`hardware_uuid_hash`);
CREATE INDEX `idx_desktop_bootstrap_devices_platform` ON `desktop_bootstrap_devices`(`platform`);
CREATE UNIQUE INDEX `idx_desktop_bootstrap_devices_device_id` ON `desktop_bootstrap_devices`(`device_id`);
CREATE TABLE `desktop_bootstrap_installations` (`id` integer PRIMARY KEY AUTOINCREMENT,`installation_id` text NOT NULL,`device_id` text,`platform` text NOT NULL,`official_build` numeric DEFAULT false,`build_channel` text NOT NULL,`app_version` text,`last_startup_id` text,`last_challenge_id` text,`last_bootstrap_status` text,`last_support_id` text,`first_seen_at` integer,`last_seen_at` integer,`extra_data` JSON,`created_at` integer,`updated_at` integer);
CREATE INDEX `idx_desktop_bootstrap_installations_last_bootstrap_status` ON `desktop_bootstrap_installations`(`last_bootstrap_status`);
CREATE INDEX `idx_desktop_bootstrap_installations_last_challenge_id` ON `desktop_bootstrap_installations`(`last_challenge_id`);
CREATE INDEX `idx_desktop_bootstrap_installations_last_startup_id` ON `desktop_bootstrap_installations`(`last_startup_id`);
CREATE INDEX `idx_desktop_bootstrap_installations_build_channel` ON `desktop_bootstrap_installations`(`build_channel`);
CREATE INDEX `idx_desktop_bootstrap_installations_official_build` ON `desktop_bootstrap_installations`(`official_build`);
CREATE INDEX `idx_desktop_bootstrap_installations_platform` ON `desktop_bootstrap_installations`(`platform`);
CREATE INDEX `idx_desktop_bootstrap_installations_device_id` ON `desktop_bootstrap_installations`(`device_id`);
CREATE UNIQUE INDEX `idx_desktop_bootstrap_installations_installation_id` ON `desktop_bootstrap_installations`(`installation_id`);
CREATE TABLE `desktop_bootstrap_challenges` (`id` integer PRIMARY KEY AUTOINCREMENT,`challenge_id` text NOT NULL,`startup_id` text NOT NULL,`installation_id` text NOT NULL,`platform` text NOT NULL,`build_channel` text NOT NULL,`official_build` numeric DEFAULT false,`challenge` text NOT NULL,`expires_at` integer,`consumed_at` integer,`created_at` integer);
CREATE INDEX `idx_desktop_bootstrap_challenges_consumed_at` ON `desktop_bootstrap_challenges`(`consumed_at`);
CREATE INDEX `idx_desktop_bootstrap_challenges_expires_at` ON `desktop_bootstrap_challenges`(`expires_at`);
CREATE INDEX `idx_desktop_bootstrap_challenges_official_build` ON `desktop_bootstrap_challenges`(`official_build`);
CREATE INDEX `idx_desktop_bootstrap_challenges_build_channel` ON `desktop_bootstrap_challenges`(`build_channel`);
CREATE INDEX `idx_desktop_bootstrap_challenges_platform` ON `desktop_bootstrap_challenges`(`platform`);
CREATE INDEX `idx_desktop_bootstrap_challenges_installation_id` ON `desktop_bootstrap_challenges`(`installation_id`);
CREATE INDEX `idx_desktop_bootstrap_challenges_startup_id` ON `desktop_bootstrap_challenges`(`startup_id`);
CREATE UNIQUE INDEX `idx_desktop_bootstrap_challenges_challenge_id` ON `desktop_bootstrap_challenges`(`challenge_id`);
CREATE TABLE `desktop_bootstrap_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`startup_id` text,`challenge_id` text,`installation_id` text,`device_id` text,`platform` text,`build_channel` text,`event_type` text NOT NULL,`outcome` text NOT NULL,`support_id` text,`request_data` JSON,`response_data` JSON,`created_at` integer);
CREATE INDEX `idx_desktop_bootstrap_events_created_at` ON `desktop_bootstrap_events`(`created_at`);
CREATE INDEX `idx_desktop_bootstrap_events_support_id` ON `desktop_bootstrap_events`(`support_id`);
CREATE INDEX `idx_desktop_bootstrap_events_outcome` ON `desktop_bootstrap_events`(`outcome`);
CREATE INDEX `idx_desktop_bootstrap_events_event_type` ON `desktop_bootstrap_events`(`event_type`);
CREATE INDEX `idx_desktop_bootstrap_events_build_channel` ON `desktop_bootstrap_events`(`build_channel`);
CREATE INDEX `idx_desktop_bootstrap_events_platform` ON `desktop_bootstrap_events`(`platform`);
CREATE INDEX `idx_desktop_bootstrap_events_device_id` ON `desktop_bootstrap_events`(`device_id`);
CREATE INDEX `idx_desktop_bootstrap_events_installation_id` ON `desktop_bootstrap_events`(`installation_id`);
CREATE INDEX `idx_desktop_bootstrap_events_challenge_id` ON `desktop_bootstrap_events`(`challenge_id`);
CREATE INDEX `idx_desktop_bootstrap_events_startup_id` ON `desktop_bootstrap_events`(`startup_id`);
CREATE TABLE `agent_sessions` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`title` text NOT NULL,`workspace_root` text,`active_document_path` text,`model_id` text,`extra_data` JSON,`created_at` integer,`updated_at` integer,`deleted_at` integer);
CREATE INDEX `idx_agent_sessions_deleted_at` ON `agent_sessions`(`deleted_at`);
CREATE INDEX `idx_agent_sessions_user_id` ON `agent_sessions`(`user_id`);
CREATE TABLE `agent_session_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`session_key` text NOT NULL,`seq` integer NOT NULL,`event_type` text NOT NULL,`body` JSON NOT NULL,`created_at` integer NOT NULL);
CREATE UNIQUE INDEX `idx_agent_session_events_session_seq` ON `agent_session_events`(`session_key`,`seq`);
CREATE TABLE `desktop_hooks` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`name` text NOT NULL,`event` text NOT NULL,`matcher` text,`command` text NOT NULL,`workdir` text,`timeout_seconds` integer NOT NULL DEFAULT 5,`enabled` numeric NOT NULL DEFAULT true,`last_run_at` integer,`last_exit_code` integer,`created_at` integer,`updated_at` integer,`deleted_at` integer);
CREATE INDEX `idx_desktop_hooks_deleted_at` ON `desktop_hooks`(`deleted_at`);
CREATE INDEX `idx_desktop_hooks_enabled` ON `desktop_hooks`(`enabled`);
CREATE INDEX `idx_desktop_hook_user_event` ON `desktop_hooks`(`user_id`,`event`);
CREATE TABLE `desktop_notification_policies` (`user_id` integer PRIMARY KEY AUTOINCREMENT,`system_notifications_enabled` numeric NOT NULL DEFAULT true,`on_task_completed` numeric NOT NULL DEFAULT true,`on_task_failed` numeric NOT NULL DEFAULT true,`on_user_input_needed` numeric NOT NULL DEFAULT true,`long_running_threshold_seconds` integer NOT NULL DEFAULT 0,`created_at` integer,`updated_at` integer);
CREATE TABLE `form_sync_workflows` (`id` text,`user_id` integer,`name` text,`template_id` text,`binding_id` text,`remote_source_id` text,`public_url` text,`published` numeric NOT NULL DEFAULT false,`document_id` text,`table_id` text,`fields_json` JSON,`target_json` JSON,`schedule_enabled` numeric,`interval_minutes` integer,`status` text,`cursor_id` integer,`last_sync_at` integer,`next_sync_at` integer,`last_error` text,`synced_submissions` integer,`created_at` integer,`updated_at` integer,PRIMARY KEY (`id`));
CREATE INDEX `idx_form_sync_workflows_status` ON `form_sync_workflows`(`status`);
CREATE INDEX `idx_form_sync_due` ON `form_sync_workflows`(`schedule_enabled`,`next_sync_at`);
CREATE INDEX `idx_form_sync_workflows_remote_source_id` ON `form_sync_workflows`(`remote_source_id`);
CREATE UNIQUE INDEX `idx_form_sync_workflows_binding_id` ON `form_sync_workflows`(`binding_id`);
CREATE INDEX `idx_form_sync_workflows_user_id` ON `form_sync_workflows`(`user_id`);
CREATE UNIQUE INDEX `idx_form_sync_target` ON `form_sync_workflows`(`user_id`,`template_id`,`document_id`,`table_id`);
CREATE TABLE `form_sync_items` (`id` integer PRIMARY KEY AUTOINCREMENT,`workflow_id` text,`submission_id` text,`record_id` text,`completed_at` integer,`created_at` integer,`updated_at` integer);
CREATE INDEX `idx_form_sync_items_completed_at` ON `form_sync_items`(`completed_at`);
CREATE UNIQUE INDEX `idx_form_sync_item` ON `form_sync_items`(`workflow_id`,`submission_id`);
CREATE TABLE `connections` (`id` text,`user_id` integer,`channel` text,`name` text,`settings_json` JSON,`secret_json` JSON,`status` text,`last_verified_at` integer,`last_error_code` text,`last_error_message` text,`created_at` integer,`updated_at` integer,PRIMARY KEY (`id`));
CREATE INDEX `idx_connections_user_channel` ON `connections`(`user_id`,`channel`);
CREATE TABLE `workflows` (`id` text,`user_id` integer,`name` text,`connection_json` JSON,`secret_json` JSON,`target_json` JSON,`schedule_enabled` numeric,`interval_minutes` integer,`include_attachments` numeric,`status` text,`last_sync_at` integer,`next_sync_at` integer,`last_error` text,`synced_messages` integer,`cursor_uid_validity` integer,`cursor_uid` integer,`created_at` integer,`updated_at` integer,PRIMARY KEY (`id`));
CREATE INDEX `idx_workflows_status` ON `workflows`(`status`);
CREATE INDEX `idx_email_sync_due` ON `workflows`(`schedule_enabled`,`next_sync_at`);
CREATE INDEX `idx_email_sync_user` ON `workflows`(`user_id`);
CREATE TABLE `sync_items` (`id` integer PRIMARY KEY AUTOINCREMENT,`workflow_id` text,`mailbox` text,`uid_validity` integer,`uid` integer,`document_path` text,`status` text,`last_error` text,`completed_at` integer,`created_at` integer,`updated_at` integer);
CREATE INDEX `idx_sync_items_completed_at` ON `sync_items`(`completed_at`);
CREATE INDEX `idx_sync_items_status` ON `sync_items`(`status`);
CREATE UNIQUE INDEX `idx_email_sync_item_identity` ON `sync_items`(`workflow_id`,`mailbox`,`uid_validity`,`uid`);
CREATE TABLE `sync_runs` (`id` text,`workflow_id` text,`user_id` integer,`mode` text,`status` text,`discovered_messages` integer,`processed_messages` integer,`imported` integer,`updated` integer,`skipped` integer,`failed` integer,`current_batch` integer,`table_path` text,`error` text,`cancel_requested` numeric,`started_at` integer,`finished_at` integer,`created_at` integer,`updated_at` integer,PRIMARY KEY (`id`));
CREATE INDEX `idx_email_sync_run_status` ON `sync_runs`(`status`);
CREATE INDEX `idx_email_sync_run_user` ON `sync_runs`(`user_id`);
CREATE INDEX `idx_email_sync_run_workflow` ON `sync_runs`(`workflow_id`);
